SET lock_timeout = '2s'; SET statement_timeout = '120s'; CREATE INDEX IF NOT EXISTS official_events_home_time_idx ON public.official_events (home_team_source_id, starts_at DESC); CREATE INDEX IF NOT EXISTS official_events_away_time_idx ON public.official_events (away_team_source_id, starts_at DESC); CREATE INDEX IF NOT EXISTS official_events_af_time_source_idx ON public.official_events (starts_at, source_id) WHERE source_id LIKE 'af:%'; CREATE INDEX IF NOT EXISTS api_football_public_team_time_idx ON public.api_football_data (kind, ((payload -> 'team') ->> 'name'), updated_at DESC) WHERE kind IN ('coach', 'injury'); CREATE INDEX IF NOT EXISTS api_football_injury_league_time_idx ON public.api_football_data (((payload -> 'league') ->> 'id'), updated_at DESC) WHERE kind = 'injury'; ANALYZE public.official_events; ANALYZE public.api_football_data;
